import type React from "react";

export interface AspectRatioProps {
  children: React.ReactNode;
  ratio?: number;
  className?: string;
  style?: React.CSSProperties;
}

"use client";
import { cn } from "@/lib/utils";

import type { AspectRatioProps } from "./aspect-ratio.types";

export function AspectRatio({ children, ratio = 16 / 9, className, style }: AspectRatioProps) {
  return (
    <div style={{ paddingBottom: `${(1 / ratio) * 100}%`, position: "relative", ...style }} className={cn("w-full", className)}>
      <div className="absolute inset-0">{children}</div>
    </div>
  );
}
